using System.Reflection;
using System.Runtime.InteropServices;
using OcctSharp.CopiedCollections;
using OcctSharp.Numeric;
using OcctSharp.OwnedValues;
namespace OcctSharp.Runtime.Tests;
public sealed class NumericMatricesTests {
 static MathMatrix Matrix(double[] data,int rows,int cols,int lr=1,int lc=1)=>MathMatrix.FromValues(new(data,rows,cols,lr,lc));
 static void Near(double expected,double actual,double tolerance=1e-10)=>Assert.InRange(Math.Abs(expected-actual),0,tolerance);
 [Fact]public void PublicBasisSolveGeometryAndStepWorkflow()=>OcctSharp.Tests.Shared.BatchALNumericWorkflow.Run();
 [Fact]public void CopiesAndFunctionalEditsPreserveShiftedDomains(){double[] data=[1,2,3,4,5,6];using var a=Matrix(data,2,3,-4,7);data[0]=99;using var clone=a.Clone();using var row=a.WithRow(-3,[8,9,10]);using var col=a.WithColumn(8,[11,12]);Assert.Equal(1,a.Snapshot()[-4,7]);Assert.Equal(8,row.Snapshot()[-3,7]);Assert.Equal(12,col.Snapshot()[-3,8]);Assert.Equal(new double[]{1,2,3},a.RowSnapshot(-4).ToArray());Assert.Equal(7,a.RowSnapshot(-4).RowLower);Assert.Equal(new double[]{2,5},a.ColumnSnapshot(8).ToArray());a.Dispose();Assert.Equal(new double[]{1,2,3,4,5,6},clone.Snapshot().ToArray());var detached=clone.Snapshot();detached.ToArray()[0]=99;clone.Dispose();Assert.Equal(1,detached[-4,7]);}
 [Fact]public void ProductsTransposeAndScalarOperationsHaveIndependentResults(){using var a=Matrix([1,2,3,4,5,6],2,3,-4,7);using var b=Matrix([2,1,0,1,3,2],2,3,10,-2);using var sum=a.Added(b);using var sub=a.Subtracted(b);Assert.Equal(new double[]{3,3,3,5,8,8},sum.Snapshot().ToArray());Assert.Equal(new double[]{-1,1,3,3,2,4},sub.Snapshot().ToArray());using var tr=a.Transposed();Assert.Equal(7,tr.LowerRow());Assert.Equal(-4,tr.LowerCol());Assert.Equal(new double[]{1,4,2,5,3,6},tr.Snapshot().ToArray());using var product=a.Multiplied(tr);Assert.Equal(new double[]{14,32,32,77},product.Snapshot().ToArray());using var tp=a.TransposeMultiplied(b);Assert.Equal(new double[]{6,13,8,9,17,10,12,21,12},tp.Snapshot().ToArray());Assert.Equal(7,tp.LowerRow());Assert.Equal(-2,tp.LowerCol());using var scale=a.Multiplied(2);using var ts=a.TMultiplied(2);using var divided=scale.Divided(2);using var neg=a.Opposite();Assert.Equal(scale.Snapshot().ToArray(),ts.Snapshot().ToArray());Assert.Equal(a.Snapshot().ToArray(),divided.Snapshot().ToArray());Assert.Equal(-6,neg.Snapshot()[-3,9]);Assert.Equal(new double[]{14,32},a.MultiplyVector([1,2,3]).ToArray());using var outer=MathMatrix.OuterProduct([2,3],[4,5,6],-2,8);Assert.Equal(new double[]{8,10,12,12,15,18},outer.Snapshot().ToArray());}
 [Theory][InlineData(NumericSolver.Gauss)][InlineData(NumericSolver.Householder)][InlineData(NumericSolver.SingularValueDecomposition)]
 public void SolversReturnDetachedMultipleRightHandSides(NumericSolver solver){using var a=Matrix([3,1,1,2],2,2,-2,5);using var b=Matrix([7,5,5,5],2,2,20,-7);var result=a.Solve(b,solver);Assert.True(result.IsDone);Near(0,result.ResidualNorm!.Value);Near(1.8,result.Values![5,-7]);Near(1.6,result.Values[6,-7]);Near(1,result.Values[5,-6]);Near(2,result.Values[6,-6]);Assert.Equal(new double[]{7,5,5,5},b.Snapshot().ToArray());a.Dispose();b.Dispose();Near(1.8,result.Values[5,-7]);}
 [Fact]public void SingleRhsAndInversePathsMatchAnalyticalSolution(){using var a=Matrix([3,1,1,2],2,2,-2,5);using var b=Matrix([7,5],2,1);foreach(var solver in Enum.GetValues<NumericSolver>()){var r=a.Solve(b,solver);Near(1.8,r.Values![5,1]);}using var inverse=a.Inverse();Near(0.4,inverse.Snapshot()[-2,5]);var gauss=a.GaussInverse();Assert.True(gauss.IsDone);Near(5,gauss.Determinant!.Value);Near(0.4,gauss.Values![5,-2]);var pseudo=a.PseudoInverse();Near(-0.2,pseudo.Values![5,-1]);}
 [Fact]public void HouseholderLeastSquaresAndSubmatrixUseCorrectDomains(){using var a=Matrix([1,0,1,1,1,2],3,2,-3,4);using var b=Matrix([1,2,4],3,1);var r=a.Solve(b,NumericSolver.Householder);Near(5.0/6,r.Values![4,1]);Near(1.5,r.Values[5,1]);Near(Math.Sqrt(1.0/6),r.ResidualNorm!.Value);using var big=Matrix([99,99,99,99,99,1,0,99,99,1,1,99,99,1,2,99],4,4,-4,3);var selected=big.SolveSubmatrix(b,-3,-1,4,5);Near(r.Values[4,1],selected.Values![4,1]);Near(r.ResidualNorm.Value,selected.ResidualNorm!.Value);}
 [Fact]public void SingularAndRankDeficientOutcomesDoNotPublishUninitializedValues(){using var a=Matrix([1,2,2,4],2,2);using var b=Matrix([3,6],2,1);foreach(var solver in new[]{NumericSolver.Gauss,NumericSolver.Householder}){var r=a.Solve(b,solver);Assert.False(r.IsDone);Assert.Null(r.Values);Assert.Null(r.ResidualNorm);Assert.Null(r.Determinant);}Assert.False(a.GaussInverse().IsDone);var svd=a.Solve(b,NumericSolver.SingularValueDecomposition);Assert.True(svd.IsDone);Near(0.6,svd.Values![1,1]);Near(1.2,svd.Values[2,1]);}
 [Fact]public void SvdTolerancesAreIndependentAndUnderdeterminedSolutionsAreMinimumNorm(){using var a=Matrix([1,0,0,1e-5],2,2);var loose=a.PseudoInverse(1e-3);var tight=a.PseudoInverse(1e-8);Near(0,loose.Values![2,2]);Near(1e5,tight.Values![2,2],1e-8);using var wide=Matrix([1,0,1,0,1,1],2,3);using var b=Matrix([1,1],2,1);var r=wide.Solve(b,NumericSolver.SingularValueDecomposition);Near(1.0/3,r.Values![1,1]);Near(1.0/3,r.Values[2,1]);Near(2.0/3,r.Values[3,1]);}
 [Fact]public void InvalidDimensionsAndNonfiniteInputsFailWithoutChangingOwners(){using var a=Matrix([1,2,3,4],2,2);using var wrong=Matrix([1,2,3],3,1);Assert.Throws<ArgumentException>(()=>a.Solve(wrong));Assert.Throws<ArgumentException>(()=>a.Added(wrong));Assert.Throws<ArgumentException>(()=>a.Multiplied(wrong));Assert.Throws<ArgumentException>(()=>a.WithRow(0,[1,2]));Assert.Throws<ArgumentException>(()=>a.WithColumn(1,[1]));Assert.Throws<ArgumentException>(()=>a.Divided(0));Assert.Throws<ArgumentException>(()=>a.Multiplied(double.NaN));Assert.Throws<ArgumentException>(()=>Matrix([double.PositiveInfinity],1,1));Assert.Throws<ArgumentException>(()=>a.Solve(a,tolerance:0));Assert.Throws<ArgumentOutOfRangeException>(()=>a.Solve(a,(NumericSolver)10));Assert.Equal(new double[]{1,2,3,4},a.Snapshot().ToArray());a.Dispose();Assert.Throws<ObjectDisposedException>(()=>a.Clone());}
 [Fact]public void SvdInternalWorkspaceLimitIsCheckedBeforeAllocation(){using var a=Matrix(new double[1025],1,1025);Assert.Throws<ArgumentException>(()=>a.PseudoInverse());}
 [Fact]public void BasisDerivativesMatchBernsteinReferenceAndClampedEndpoints(){var b=SplineMatrixSystem.EvaluateBasis([0,0,0,1,1,1],2,0.25,2);Near(0.5625,b[0,1]);Near(0.375,b[0,2]);Near(0.0625,b[0,3]);Near(-1.5,b[1,1]);Near(1,b[1,2]);Near(0.5,b[1,3]);Near(2,b[2,1]);Near(-4,b[2,2]);Near(2,b[2,3]);Near(1,SplineMatrixSystem.EvaluateBasis([0,0,0,1,1,1],2,1)[0,3]);}
 [Theory][InlineData(2,false)][InlineData(3,false)][InlineData(2,true)][InlineData(3,true)]
 public void AllTypedBandedVariantsCopyCoordinatesAndWeights(int dimension,bool homogeneous){using var s=SplineMatrixSystem.Create([0,0,0,1,1,1],2,[0,0.5,1],[0,0,0]);double[] p=dimension==2?[0,0,2,2.0/3,4,0]:[0,0,0,2,2.0/3,0,4,0,0];double[] weights=[1,1.5,1];if(homogeneous)for(int j=0;j<dimension;++j)p[dimension+j]*=1.5;var r=s.Solve(new(p,3,dimension),weights,homogeneous);Assert.True(r.IsDone);Near(homogeneous?4:2,r.Values![2,1]);Near(homogeneous?2:1,r.Values[2,2]);Near(2,r.Values[2,dimension+1]);Assert.Equal(1.5,weights[1]);var plain=s.Solve(new(dimension==2?new double[]{0,0,2,0.5,4,0}:new double[]{0,0,0,2,0.5,0,4,0,0},3,dimension));Near(1,plain.Values![2,2]);}
 [Fact]public void ContactOrderInterpolationAndFailedFactorizationAreExplicit(){using var s=SplineMatrixSystem.Create([0,0,0,0,1,1,1,1],3,[0,0,1,1],[0,1,1,0]);var r=s.Solve(new([0.0,0,1,0,1,2,1,1],4,2));Assert.True(r.IsDone);Near(1.0/3,r.Values![2,1]);Near(0,r.Values[2,2]);Near(1.0/3,r.Values[3,2]);using var singular=SplineMatrixSystem.Create([0,0,0,1,1,1],2,[0,0,1],[0,0,0]);Assert.NotEqual(0,singular.Status);Assert.True(singular.PivotIndex>0);var failed=singular.Solve(new(new double[6],3,2));Assert.False(failed.IsDone);Assert.Null(failed.Values);}
 [Fact]public void InvalidKnotsBandWritesAndZeroSolvedWeightAreRejected(){Assert.Throws<ArgumentException>(()=>SplineMatrixSystem.EvaluateBasis([0,0,0,1,1,1],2,2));Assert.Throws<ArgumentException>(()=>SplineMatrixSystem.EvaluateBasis([0,0,0,0,1,1,1],2,0.5));Assert.Throws<ArgumentException>(()=>SplineMatrixSystem.EvaluateBasis([0,0,0,1,1,1],2,0.5,3));Assert.Throws<ArgumentException>(()=>SplineMatrixSystem.Create([0,0,0,0.5,1,1,1],2,[1,1,1,1],[0,0,0,0]));using var s=SplineMatrixSystem.Create([0,0,0,1,1,1],2,[0,0.5,1],[0,0,0]);Assert.Throws<ArgumentException>(()=>s.Solve(new(new double[6],3,2),[]));var r=s.Solve(new(new double[6],3,2),[0,0,0]);Assert.Equal(4,r.Status);Assert.Null(r.Values);}
 [Fact]public void ImmutableBandSupportsConcurrentSolvesAndDisposal(){for(int attempt=0;attempt<25;++attempt){using var s=SplineMatrixSystem.Create([0,0,1,1],1,[0,1],[0,0]);var errors=new System.Collections.Concurrent.ConcurrentQueue<Exception>();Parallel.For(0,12,i=>{try{if(i==0)s.Dispose();else{var r=s.Solve(new([0.0,0,1,2],2,2));Assert.True(r.IsDone);}}catch(ObjectDisposedException){}catch(Exception e){errors.Enqueue(e);}});Assert.Empty(errors);}}
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]unsafe delegate int CopyRaw(nint token,double* data,int capacity,int* lr,int* rows,int* lc,int* cols);
 [Fact]public void NonpivotingHermiteFailureRetainsOriginalMatrixAndDenseAlternative(){using var s=SplineMatrixSystem.Create([0,0,0,0,1,1,1,1],3,[0,0,1,1],[0,1,0,1]);Assert.NotEqual(0,s.Status);var original=s.MatrixSnapshot();Near(1,original[1,4]);Near(-3,original[2,3]);Near(3,original[2,4]);using var dense=Matrix([1,0,0,0,-3,3,0,0,0,0,0,1,0,0,-3,3],4,4);using var rhs=Matrix([0,1,1,1],4,1);var solved=dense.Solve(rhs);Assert.True(solved.IsDone);Near(1.0/3,solved.Values![2,1]);var failed=s.Solve(new(new double[8],4,2));Assert.False(failed.IsDone);Assert.Null(failed.Values);Assert.Equal(original.ToArray(),s.MatrixSnapshot().ToArray());}
 [Fact]public void MultipleSpanBasisRetainsLocalPoleIndexDomain(){var basis=SplineMatrixSystem.EvaluateBasis([0,0,0,0.5,1,1,1],2,0.75,1);Assert.Equal(2,basis.ColumnLower);Near(1,basis.ToArray().Take(3).Sum());Near(0,basis.ToArray().Skip(3).Sum());Near(0.125,basis[0,2]);Near(0.625,basis[0,3]);Near(0.25,basis[0,4]);}
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]unsafe delegate int CreateRaw(double* data,int count,int lr,int rows,int lc,int cols,out nint result);
 [Fact]public unsafe void RawCapacityAliasingBoundsAndStaleTokensFailSafely(){using var a=Matrix([1,2,3,4],2,2);var field=typeof(MathMatrix).GetField("_handle",BindingFlags.Instance|BindingFlags.NonPublic)!;nint token=((SafeHandle)field.GetValue(a)!).DangerousGetHandle();nint library=NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory,"occt","OcctSharp.Native.dll"));try{var copy=Marshal.GetDelegateForFunctionPointer<CopyRaw>(NativeLibrary.GetExport(library,"occtsharp_numeric_matrix_copy"));var create=Marshal.GetDelegateForFunctionPointer<CreateRaw>(NativeLibrary.GetExport(library,"occtsharp_numeric_matrix_create"));double* data=stackalloc double[4]{99,99,99,99};int lr=9,rows=9,lc=9,cols=9;Assert.NotEqual(0,copy(token,data,3,&lr,&rows,&lc,&cols));Assert.Equal(99,data[0]);Assert.Equal(0,rows);Assert.NotEqual(0,copy(token,data,4,&lr,&lr,&lc,&cols));Assert.NotEqual(0,create(data,4,int.MaxValue/2,2,1,2,out var p));Assert.Equal(0,p);a.Dispose();Assert.NotEqual(0,copy(token,null,0,&lr,&rows,&lc,&cols));Assert.NotEqual(0,copy(0,null,0,&lr,&rows,&lc,&cols));}finally{NativeLibrary.Free(library);}}
}
